#!/usr/bin/env python3
"""Check the dev2 laws in references/sd/laws.md over the events one push adds to a committed state-branch history.

Usage: laws_check.py <state checkout> --before <commit> [--after <commit>] [--readme FILE]
Judges only the events of the commits in before..after (--after defaults to HEAD), each read at its own commit,
so a violation is reported in the run of the push that added it and not again. Reads committed bytes only;
changes nothing.
Exit 0 every law held. Exit 1 some law was violated. Exit 2 something could not be judged (before or after not a
commit, a range commit with no parent in this clone, a missing script, a check that crashed or printed a shape
this runner does not parse), even when another law also failed; both kinds print.
"""
import argparse
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

SCRIPTS = Path(__file__).resolve().parent
TRACEBACK = "Traceback (most recent call last)"
SENTINEL = re.compile(r"pr-merge:\d+")
TASK = re.compile(r"^(?:_archive/)?([^/]+)\.md$")
DISPATCH = re.compile(r"^(_archive/)?([^/]+)/dispatch/([^/]+\.md)$")


class Cannot(Exception):
    pass


def run(*argv, cwd=None):
    done = subprocess.run(argv, capture_output=True, cwd=cwd)
    return done.returncode, done.stdout.decode("utf-8", "replace"), done.stderr.decode("utf-8", "replace")


def git(state, *args):
    code, out, err = run("git", "-C", str(state), "-c", "core.quotepath=off", *args)
    if code:
        raise Cannot(f"git {' '.join(args[:2])} failed: {err.strip() or out.strip()}")
    return out


def commit_of(state, name):
    code, out, _ = run("git", "-C", str(state), "rev-parse", "--verify", "--quiet", f"{name}^{{commit}}")
    return out.strip() if code == 0 and out.strip() else None


def script(name):
    path = SCRIPTS / name
    if not path.is_file():
        raise Cannot(f"script missing: {path}")
    return str(path)


def run_check(name, *args):
    code, out, err = run(sys.executable, script(name), *args)
    if TRACEBACK in out or TRACEBACK in err:
        raise Cannot(f"{name} crashed: {(err or out).strip().splitlines()[-1]}")
    if code not in (0, 1):
        first = (out or err).strip().splitlines()
        raise Cannot(f"{name} exited {code}: {first[0] if first else 'no output'}")
    lines = [line for line in out.splitlines() if line.strip()]
    if code == 1 and not lines:
        note = (err.strip().splitlines() or ["stderr empty"])[-1]
        raise Cannot(f"{name} exited 1 with no output: {note}")
    return code, lines


def ledger():
    script("decision_ledger.py")
    sys.path.insert(0, str(SCRIPTS))
    import decision_ledger
    return decision_ledger


def frontmatter_pr(text):
    lines, _ = ledger().split_task(text)
    for line in lines or []:
        if line.startswith("pr:"):
            return ledger().unquote(line[3:])
    return None


def readme_extensions(path):
    try:
        lines, _ = ledger().split_task(Path(path).read_text())
    except OSError as err:
        raise Cannot(f"README unreadable: {err}")
    if lines is None:
        raise Cannot(f"README {path} has no frontmatter, so extensions: cannot be read")
    for i, line in enumerate(lines):
        if line.startswith("extensions:"):
            value = line[len("extensions:"):].strip()
            if value.startswith("[") and value.endswith("]"):
                return set(re.findall(r"[\w-]+", value))
            if not value:
                block = []
                for nxt in lines[i + 1:]:
                    if not nxt.lstrip().startswith("- "):
                        break
                    block.append(nxt.lstrip()[2:].strip())
                return set(block)
            raise Cannot(f"README {path}: extensions: is neither a [list] nor a block list")
    return set()


def walk(state, before, after):
    span = f"{before}..{after}"
    for line in git(state, "rev-list", "--no-merges", "--parents", span).splitlines():
        sha, *parents = line.split()
        if not parents:
            raise Cannot(f"{sha[:12]} has no parent here, so what it adds cannot be told from a truncated past")
    commits = []
    for line in git(state, "log", "--no-merges", "--reverse", "-M", "--name-status", "--format=%x01%H", span).splitlines():
        if line.startswith("\x01"):
            commits.append((line[1:], []))
        elif line:
            status, *paths = line.split("\t")
            commits[-1][1].append((status[0], paths[0], paths[-1]))
    return commits


def sentinel_at(state, rev, path):
    code, out, _ = run("git", "-C", str(state), "show", f"{rev}:{path}")
    return code == 0 and SENTINEL.fullmatch(frontmatter_pr(out) or "") is not None


def l1_observer_before_sentinel(ctx):
    script("observer_check.py")
    if ctx.readme is None:
        raise Cannot("L1 needs --readme FILE to read extensions:")
    if "learn" not in readme_extensions(ctx.readme):
        return 0, [], "0 events judged (README lists no learn)"
    judged, violations = 0, []
    for commit, changes in ctx.commits:
        for status, old, new in changes:
            task = TASK.match(new)
            if status not in "AMR" or not task or task[1] == "README":
                continue
            if not sentinel_at(ctx.state, commit, new) or (status != "A" and sentinel_at(ctx.state, f"{commit}^", old)):
                continue
            judged += 1
            code, lines = run_check("observer_check.py", str(ctx.state), task[1], "--rev", commit)
            if code == 1:
                if not re.match(r"observer report (?:not committed|blank): ", lines[0] if lines else ""):
                    raise Cannot(f"observer_check.py exited 1 with output this runner does not parse: {lines[:1]}")
                violations.append(f"violation: L1 observer-before-sentinel task={task[1]} commit={commit[:12]} {lines[0]}")
    return judged, violations, None


def l2_dispatch_record_complete(ctx):
    script("dispatch_records.py")
    groups = {}
    for commit, changes in ctx.commits:
        for status, old, new in changes:
            if status in "AR" and DISPATCH.match(new) and (status == "A" or not DISPATCH.match(old)):
                groups.setdefault((commit, new.rsplit("/dispatch/", 1)[0]), []).append(new)
    judged, hit = 0, {}
    for (commit, folder), paths in groups.items():
        with tempfile.TemporaryDirectory() as tmp:
            for path in git(ctx.state, "ls-tree", "--name-only", commit, f"{folder}/dispatch/").split("\n"):
                if DISPATCH.match(path):
                    (Path(tmp) / path).parent.mkdir(parents=True, exist_ok=True)
                    (Path(tmp) / path).write_text(git(ctx.state, "show", f"{commit}:{path}"))
            mine = {path.rsplit("/", 1)[1]: (path, commit) for path in paths}
            judged += len(mine)
            readme = ["--readme", str(ctx.readme)] if ctx.readme else []
            code, lines = run_check("dispatch_records.py", *readme, str(Path(tmp) / folder))
            for line in lines if code == 1 else []:
                if not ctx.readme and line.startswith("extensions not checked: "):
                    continue
                match = re.fullmatch(r"([^/]+\.md): (needs .+|[\w-]+ worker instruction .+)", line)
                if not match:
                    raise Cannot(f"dispatch_records.py exited 1 with output this runner does not parse: {line}")
                if match[1] in mine:
                    hit.setdefault(mine[match[1]], []).append(match[2])
            files = [str(Path(tmp) / path) for path in paths]
            code, lines = run_check("dispatch_records.py", "--names", *files)
            for line in lines if code == 1 else []:
                match = re.fullmatch(r"(.+\.md):(\d+): (bare package script name \S+|no 'Candidate: <40-hex head>' line)(?:;.*)?", line)
                if not match:
                    raise Cannot(f"dispatch_records.py --names exited 1 with output this runner does not parse: {line}")
                key = next((v for v in mine.values() if str(Path(tmp) / v[0]) == match[1]), None)
                if key:
                    hit.setdefault(key, []).append(f"{match[3]} (line {match[2]})")
    violations = [f"violation: L2 dispatch-record-complete record={path} commit={commit[:12]} {part}"
                  for (path, commit), parts in sorted(hit.items()) for part in parts]
    return judged, violations, None, len(hit)


LAWS = {
    "L1": ("observer-before-sentinel", l1_observer_before_sentinel),
    "L2": ("dispatch-record-complete", l2_dispatch_record_complete),
}


class Context:
    def __init__(self, state, span, commits, readme):
        self.state, self.span, self.commits, self.readme = state, span, commits, readme


def judge(ctx, law_id, spec):
    name, fn = spec
    judged, violations, note, *distinct = fn(ctx)
    violated = distinct[0] if distinct else len(violations)
    head = note or f"{judged} events judged in {ctx.span}, {violated} violated"
    return violated, [f"{law_id} {name}: {head}"], violations


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("state")
    parser.add_argument("--before", required=True)
    parser.add_argument("--after", default="HEAD")
    parser.add_argument("--readme")
    opts = parser.parse_args(sys.argv[1:] if argv is None else argv)
    state = Path(opts.state)
    problems = []
    if run("git", "-C", str(state), "rev-parse", "--is-inside-work-tree")[1].strip() != "true":
        problems.append(f"{state} is not a git work tree")
    else:
        before, after = commit_of(state, opts.before), commit_of(state, opts.after)
        problems += [f"{flag} {given} names no commit in {state}"
                     for flag, given, found in (("--before", opts.before, before), ("--after", opts.after, after)) if found is None]
    if not problems:
        try:
            commits = walk(state, before, after)
        except Cannot as err:
            problems.append(str(err))
    if problems:
        for problem in problems:
            print(f"cannot judge: {problem}")
        return 2
    ctx = Context(state, f"{before[:12]}..{after[:12]}", commits, opts.readme)
    total_violated, cannot = 0, []
    for law_id, spec in LAWS.items():
        try:
            violated, heads, violations = judge(ctx, law_id, spec)
        except Cannot as err:
            cannot.append(f"{law_id} {spec[0]}: cannot judge: {err}")
            continue
        total_violated += violated
        print("\n".join(heads + violations))
    for line in cannot:
        print(line)
    return 2 if cannot else (1 if total_violated else 0)


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""Check a task's dispatch records: each needs a Dispatched line with a full SHA, a Model line,
non-empty Checklist and Scope notes sections, a `Package root:` line with an absolute path inside Scope notes, a scope-notes
line naming `main` as the completion recipient, and a checklist that is not only pointer lines (a record name plus only
words from POINTER_WORDS, as in "Same checklist as implementation-2."); a pointer worded outside that set, such as
"Reuse the checklist of implementation-2.", passes.
When the workflow README lists an extension whose EXTENSION.md has an `Instruction FO adds to the scope notes`
bullet, the first record of its `Joins:` stage (`implementation-1.md`) also needs that bullet's script paths with
`<package>` replaced by the record's own `Package root:` value, or a line `<name> not run: <reason>`.

Usage: dispatch_records.py [--readme FILE] <task folder or task .md file>
       dispatch_records.py --names <record file>...
       dispatch_records.py --newest <state checkout> <task slug>
Exit 1 naming each record that lacks a part, or when the task has no dispatch records. The README is FILE, else the
nearest README.md above the task folder with an `entity-type:` line; with neither, the run prints
`extensions not checked: no workflow README above <folder>` and its exit code is unchanged. A missing FILE exits 2.
--names prints `<file>:<line>: bare package script name <NAME>` for each package script (a .py file
directly under <package>/scripts/ or <package>/extensions/<name>/) written with no directory part in the
Checklist or Scope notes section (the whole file when it has neither heading), and exits 1 when any is found.
--names also prints `<file>:1: no 'Candidate: <40-hex head>' line; ...` for a `validation-<N>.md` directly in a `dispatch/` folder
whose text above its first `## ` heading has no line delivery_gate.py accepts; --newest does not.
--newest runs that scan on the file added by the latest commit that adds a file under <slug>/dispatch/, read as it
is on disk: exit 0 when it is clean or the task has no record, 1 when a name is found, 2 when git cannot read the state.
"""
import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from delivery_gate import CANDIDATE, RECORD  # noqa: E402
from number_guards import Misconfigured, frontmatter  # noqa: E402

PACKAGE = Path(__file__).resolve().parent.parent

PARTS = {
    "a 'Dispatched:' line with a full 40-character SHA": re.compile(r"^Dispatched:.*\b[0-9a-f]{40}\b", re.M),
    "a 'Model:' line": re.compile(r"^Model:[ \t]*\S", re.M),
    "a non-empty '## Checklist' section": re.compile(r"^## Checklist[ \t]*\n(?:[ \t]*\n)*(?!## )\S", re.M),
    "a non-empty '## Scope notes' section": re.compile(r"^## Scope notes[ \t]*\n(?:[ \t]*\n)*(?!## )\S", re.M),
    "a 'Package root:' line with an absolute path in its scope notes":
        re.compile(r"^## Scope notes\b(?:(?!^## )[\s\S])*?^Package root:[ \t]*/\S", re.M),
    "a scope-notes line naming main as the completion recipient":
        re.compile(r"^## Scope notes\b(?:(?!^## )[\s\S])*?\bcompletion(?: message)? to [`']?main(?![\w-])", re.M | re.I),
}

SCRIPT_TOKEN = re.compile(r"(?<![\w./~-])([\w-]+\.py)(?!\w)")
SCANNED = re.compile(r"^## (?:Checklist|Scope notes)[ \t]*$")


INSTRUCTION = re.compile(r"^- \*\*Instruction FO adds to the scope notes:\*\*(.*?)(?=^- \*\*|\Z)", re.M | re.S)
JOINS = re.compile(r"^- \*\*Joins:\*\*[ \t]*(\w+)", re.M)
PACKAGE_PATH = re.compile(r"<package>/(extensions/[\w-]+/[\w.-]+\.py)")
ROOT = re.compile(r"^Package root:[ \t]*(/\S+)", re.M)


POINTER_WORDS = {"same", "identical", "unchanged", "checklist", "items", "as", "in", "to", "of", "from", "the", "see", "and", "for"}


def is_pointer(line, others):
    stems = "|".join(re.escape(name) for name in others)
    rest, hits = re.subn(rf"(?<![\w-])(?:[\w./~-]*/)?(?:{stems})(?:\.md)?(?![\w-])", " ", line) if others else (line, 0)
    return bool(hits) and all(word in POINTER_WORDS for word in re.findall(r"[a-z]+", rest.lower()))


def only_points_at_records(text, others):
    match = re.search(r"^## Checklist[ \t]*\n((?:(?!^## )[\s\S])*)", text, re.M)
    lines = [line for line in match.group(1).splitlines() if line.strip()] if match else []
    return bool(lines) and all(is_pointer(line, others) for line in lines)


def declared_instructions(package, listed):
    found = []
    for name in listed:
        file = Path(package, "extensions", name, "EXTENSION.md")
        text = file.read_text() if file.is_file() else ""
        bullet, stage = INSTRUCTION.search(text), JOINS.search(text)
        paths = PACKAGE_PATH.findall(bullet.group(1)) if bullet else []
        if stage and paths:
            found.append((name, stage.group(1), paths))
    return found


def find_readme(folder):
    for parent in Path(folder).resolve().parents:
        candidate = parent / "README.md"
        if candidate.is_file() and "entity-type" in frontmatter(candidate):
            return candidate
    return None


def instruction_error(record, name, paths):
    text, root = record.read_text(), ROOT.search(record.read_text())
    if not root or re.search(rf"^.*\b{re.escape(name)} not run:[ \t]*\S", text, re.M):
        return None
    base = root.group(1).rstrip("/")
    missing = [p for p in paths if not re.search(rf"(?<![\w.~-]){re.escape(base + '/' + p)}(?=[.,`)\x22\x27]{{0,3}}(?:\s|$))", text)]
    if not missing:
        return None
    if any(f"<package>/{p}" in text for p in missing):
        return f"{record.name}: {name} worker instruction has an unsubstituted <package>; write {base}/{missing[0]}"
    return (f"{record.name}: {name} worker instruction is absent; copy the 'Instruction FO adds to the scope notes' "
            f"bullet of {base}/extensions/{name}/EXTENSION.md into the scope notes, or add a line '{name} not run: <reason>'")


def extension_errors(folder, readme, package):
    listed = re.findall(r"[\w-]+", frontmatter(readme).get("extensions", ""))
    errors = []
    for name, stage, paths in declared_instructions(package, listed):
        for record in [Path(folder, "dispatch", f"{stage}-1.md")]:
            error = instruction_error(record, name, paths) if record.is_file() else None
            if error:
                errors.append(error)
    return errors


def package_scripts(package):
    return {p.name for pattern in ("scripts/*.py", "extensions/*/*.py") for p in package.glob(pattern)}


def bare_names(text, names):
    lines = text.splitlines()
    if not any(SCANNED.match(line) for line in lines):
        scanned = range(len(lines))
    else:
        scanned, inside = [], False
        for number, line in enumerate(lines):
            if line.startswith("## "):
                inside = bool(SCANNED.match(line))
            elif inside:
                scanned.append(number)
    return [(number + 1, name) for number in scanned
            for name in dict.fromkeys(SCRIPT_TOKEN.findall(lines[number])) if name in names]


def check_names(files, package):
    names = package_scripts(package)
    found = False
    for file in files:
        for number, name in bare_names(Path(file).read_text(), names):
            print(f"{file}:{number}: bare package script name {name}")
            found = True
    return 1 if found else 0


def check_candidates(files):
    found = False
    for file in files:
        path = Path(file).resolve()
        if path.parent.name != "dispatch" or not RECORD.match(path.name):
            continue
        header = re.split(r"^## ", path.read_text(), maxsplit=1, flags=re.M)[0]
        if not CANDIDATE.search(header):
            print(f"{file}:1: no 'Candidate: <40-hex head>' line; add one per head to validate above the first '## ' heading, "
                  "then run this check again")
            found = True
    return 1 if found else 0


def check_newest(state, slug, package):
    done = subprocess.run(["git", "-C", str(state), "log", "--diff-filter=A", "--no-renames", "--relative",
                           "--name-only", "--format=", "-n", "1", "--", f"{slug}/dispatch/"],
                          capture_output=True, text=True)
    if done.returncode:
        print(f"git cannot read the dispatch records: {' '.join(done.stderr.split())}")
        return 2
    added = sorted(line for line in done.stdout.splitlines() if line.endswith(".md"))
    record = Path(state, added[-1]) if added else None
    return check_names([record], package) if record and record.is_file() else 0


def main(argv=None, package=PACKAGE):
    args = sys.argv[1:] if argv is None else argv
    if args[:1] == ["--names"] and len(args) > 1:
        return max(check_names(args[1:], package), check_candidates(args[1:]))
    if args[:1] == ["--newest"] and len(args) == 3:
        return check_newest(args[1], args[2], package)
    readme = None
    if "--readme" in args:
        at = args.index("--readme")
        given, args = args[at + 1:at + 2], args[:at] + args[at + 2:]
        if not given:
            print(__doc__.strip())
            return 2
        readme = Path(given[0])
        if not readme.is_file():
            print(f"--readme {readme}: no such file")
            return 2
    if len(args) != 1 or args[0] in ("--names", "--newest"):
        print(__doc__.strip())
        return 2
    task = Path(args[0])
    folder = task.with_suffix("") if task.suffix == ".md" else task
    records = sorted((folder / "dispatch").glob("*.md"))
    if not records:
        print(f"{folder}: no dispatch records under dispatch/")
        return 1
    errors = [f"{path.name}: needs {part}" for path in records
              for part, pattern in PARTS.items() if not pattern.search(path.read_text())]
    readme = readme or find_readme(folder)
    if readme:
        errors += extension_errors(folder, readme, package)
    names = [path.stem for path in records]
    for path in records:
        if only_points_at_records(path.read_text(), [name for name in names if name != path.stem]):
            errors.append(f"{path.name}: needs a checklist of its own, not only a reference to another dispatch record")
    for error in errors:
        print(error)
    if not readme:
        print(f"extensions not checked: no workflow README above {folder}")
    if not errors:
        print(f"{len(records)} dispatch record(s) complete")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""Check that a task's observer report is committed in the state checkout.

Usage: observer_check.py <state checkout> <task slug> [--rev REV]
Reads the committed tree at REV (default HEAD), not the disk. The report is <slug>/observer.md before the
task is archived and _archive/<slug>/observer.md after.
Exit 0 when that file is committed and not blank; stdout names it, and repeats the first line when it
starts "observer not run:"; for an archived task it adds the learn steps. Exit 1 when it is not: stdout
names the observer dispatch and the save command, each as a `next:` line.
Exit 2 when the check cannot be made (usage, not a git work tree, REV names no commit, the slug has no task at
REV): stdout names the cause. Nothing here changes the checkout.
"""
import shlex
import subprocess
import sys
from pathlib import Path

WAIVER = "observer not run:"


class Unverifiable(Exception):
    pass


def git(state, *args):
    done = subprocess.run(["git", "-C", str(state), *args], capture_output=True)
    return done.returncode, done.stdout.decode("utf-8", "replace")


def kind(state, rev, path):
    code, out = git(state, "cat-file", "-t", f"{rev}:./{path}")
    return out.strip() if code == 0 else None


def parse(args):
    rev = "HEAD"
    if "--rev" in args:
        at = args.index("--rev")
        if at + 1 >= len(args):
            raise Unverifiable("usage: --rev needs a value")
        rev = args[at + 1]
        args = args[:at] + args[at + 2:]
    if len(args) != 2 or "/" in args[1] or args[1] in ("", ".", ".."):
        raise Unverifiable("usage: observer_check.py <state checkout> <task slug> [--rev REV]")
    return Path(args[0]), args[1], rev


def locate(state, slug, rev):
    if git(state, "rev-parse", "--is-inside-work-tree")[1].strip() != "true":
        raise Unverifiable(f"{state} is not a git work tree")
    code, _ = git(state, "rev-parse", "--verify", "--quiet", f"{rev}^{{commit}}")
    if code:
        raise Unverifiable(f"--rev {rev} names no commit in {state}")
    live = kind(state, rev, f"{slug}.md") == "blob" or kind(state, rev, slug) == "tree"
    archived = kind(state, rev, f"_archive/{slug}.md") == "blob" or kind(state, rev, f"_archive/{slug}") == "tree"
    if not (live or archived):
        raise Unverifiable(f"no task file or folder for {slug} at {rev} in {state}, so a missing report "
                           "cannot be told from a mistyped slug")
    return not live and archived


def check(state, slug, rev):
    archived = locate(state, slug, rev)
    path = f"_archive/{slug}/observer.md" if archived else f"{slug}/observer.md"
    code, out = git(state, "show", f"{rev}:./{path}")
    learn = [f"next: run kc-dev-flow-2:learn for {slug}.",
             "next: send learn's notice, then the observer report unedited, in one message; answer none of its findings."]
    if code == 0 and out.strip():
        first = out.strip().splitlines()[0].strip()
        note = f" {first}" if first.startswith(WAIVER) else ""
        return 0, "\n".join([f"observer report committed: {path} at {rev}.{note}"] + (learn if archived else []))
    where = "blank" if code == 0 else "not committed"
    quoted = shlex.quote(str(state))
    commit = f"spacedock state commit {slug} --workflow-dir <workflow dir>"
    if archived:
        steps = [f"dispatch kc-dev-flow-2:observer over both path pairs, {slug}.md and {slug}/, then _archive/{slug}.md and _archive/{slug}/.",
                 f"save its report unedited as {path}.",
                 f"run `git -C {quoted} add {shlex.quote(path)} && git -C {quoted} commit -m \"<message>\" -- {shlex.quote(path)}`.",
                 f"run `{commit}`.",
                 "tell the Captain the observer ran after the archive."]
        steps = [f"next: {step}" for step in steps] + learn
    else:
        steps = [f"dispatch kc-dev-flow-2:observer with only the state checkout, {slug} and the workflow README.",
                 f"save its report unedited as {path}.",
                 f"if it cannot be dispatched, save the one line `{WAIVER} <reason>` there instead.",
                 f"run `{commit}`.",
                 "run the idle hooks again."]
        steps = [f"next: {step}" for step in steps]
    return 1, "\n".join([f"observer report {where}: {path} at {rev}."] + steps)


def main(argv=None):
    args = sys.argv[1:] if argv is None else list(argv)
    try:
        state, slug, rev = parse(args)
        code, message = check(state, slug, rev)
    except Unverifiable as err:
        print(f"cannot tell whether the observer report is committed: {err}. Hold and report the cause.")
        return 2
    print(message)
    return code


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Check what FO is about to ask the Captain to merge.

Usage: delivery_gate.py check <task file> --pr <owner/repo>#<N> --text-file <file> [--head <sha>] [--workflow-dir <dir>]

The dispatched heads are the whole `Candidate: <40-hex head>` lines above the first `## ` heading of the
highest-numbered `<task folder>/dispatch/validation-<N>.md` record; the check reads no validation verdict.
A task whose frontmatter says `profile: prod` must also pass `validation_security.py` (saved security review at
the dispatched head the PR head equals, every finding disposed); a profile that cannot be read as poc, pilot or prod holds.
The PR head is compared, as a prefix, with each line; it passes when it matches one (--head, else `gh pr view --json headRefOid`).
--text-file holds the gate question and summary: each `Second reviewer: <X> because` needs `<X> not run: <reason>`
or, in one sentence naming <X>, a `review:<id>` or `comment:<id>` token.
The PR is also read with `gh pr view` and `gh api --paginate .../pulls/<N>/files`. Exit 1 holds the ask when the head differs,
a second reviewer has no stated outcome, a prod task's security review fails, a check run on the head is not finished and
successful (an empty rollup, SKIPPED and NEUTRAL included), the PR is a draft or not mergeable, its base is not the README's
`trunk:`, or the file list is shorter than `changedFiles`. Exit 2 when the record has no Candidate line, a head, the PR or the
README cannot be read, or an input is unusable. Every problem is printed.
Exit 0 prints `point:` lines (pointers into the records and the changed paths, at most 12, each value an escaped bounded token),
one `class:` line (never, docs-only, script-with-test or other, by allowlist), the saved record `<task>/merge/ask-<N>.json`
and one last `next:` line, which is always the ask line.
"""
import argparse
import datetime
import json
import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from design_surfaces import FM_PROFILE

CANDIDATE = re.compile(r"^Candidate:[ \t]+([0-9a-f]{40})[ \t]*$", re.M)
RECORD = re.compile(r"^validation-(\d+)\.md$")
SECOND_REVIEWER = re.compile(r"Second reviewer:\s*([\w.-]+)\s+because", re.I)
OUTCOME_TOKEN = re.compile(r"\b(?:review|comment):\d+")
PR = re.compile(r"^([\w.-]+/[\w.-]+)#(\d+)$")
CONVENTIONAL = re.compile(r"^(?:feat|fix|docs|chore|refactor|test|style|perf|ci|build|revert)(?:\([\w./-]+\))?!?: \S[\x20-\x7e]{0,99}$")
CODE = {".py", ".sh", ".js", ".mjs", ".ts", ".tsx", ".jsx", ".go", ".rb"}
NEVER_PATH = [
    re.compile(r"^(?:\.github|\.claude|\.githooks)/|^\.roborev\.toml$|^scripts/"),
    re.compile(r"(?:^|/)(?:hooks|bin)/"),
    re.compile(r"(?:^|/)(?:_mods|migrations)/"),
    re.compile(r"^docs/(?:adr|dev[^/]*)(?:/|$)"),
    re.compile(r"(?:^|/)(?:skills|agents|extensions|references)/"),
    re.compile(r"(?:^|/)(?:CLAUDE|AGENTS)\.md$|(?:^|/)learning\.md$"),
    re.compile(r"(?:^|/)(?:release-please-config|\.release-please-manifest|plugin|marketplace)\.json$"),
    re.compile(r"(?:^|/)[^/]*(?:gate|budget)[^/]*$"),
    re.compile(r"(?:^|/)kc-dev-flow-2/scripts/"),
]
VALIDATION_SECTION = re.compile(r"^## Stage Report: validation[^\n]*\n(.*?)(?=^## |\Z)", re.M | re.S)
FO_DECLINES = re.compile(r"^### FO declines[ \t]*\n(.*?)(?=^#{1,3} |\Z)", re.M | re.S)
DEFERRED = re.compile(r"\bDeferred risk\b|\bdeclined\b|round-3 backlog", re.I)
NOT_RUN = re.compile(r"\b[\w.-]+ not run:\s*\S", re.I)
AC_NOT_RUN = re.compile(r"(?:\bAC-\d+\b|\bacceptance\b).*\bnot run\b", re.I)
AMENDMENT = re.compile(r"^### Amendment (\d+) — (\d{4}-\d{2}-\d{2})", re.M)
MAX_POINTS = 12
ASK = "next: ask for merge with this text."


def clean(line):
    return "".join(ch if ch.isprintable() else ch.encode("unicode_escape").decode() for ch in line)


def emit(*lines):
    for line in lines:
        print(clean(line))


def tok(value, words=6, chars=80):
    return repr(" ".join(str(value).split()[:words])[:chars])


def utcnow():
    return datetime.datetime.now(datetime.timezone.utc)


def dispatched_candidates(task):
    records = [(int(m.group(1)), path) for path in (task.with_suffix("") / "dispatch").glob("validation-*.md")
               if (m := RECORD.match(path.name))]
    if not records:
        return [], None
    path = max(records)[1]
    try:
        header = re.split(r"^## ", path.read_text(), maxsplit=1, flags=re.M)[0]
    except (OSError, UnicodeDecodeError):
        return [], path
    return CANDIDATE.findall(header), path


def gh(*args):
    try:
        done = subprocess.run(["gh", *args], capture_output=True, text=True, timeout=60)
    except (OSError, subprocess.SubprocessError) as error:
        raise RuntimeError(f"gh not runnable: {error}") from error
    if done.returncode:
        raise RuntimeError(f"gh {args[0]} {args[1]} exited {done.returncode}: {done.stderr.strip()}")
    return done.stdout


def run_gh(repo, number):
    return json.loads(gh("pr", "view", number, "--repo", repo, "--json", "headRefOid"))["headRefOid"]


def pr_facts(repo, number):
    fields = "headRefOid,isDraft,mergeable,statusCheckRollup,title,headRefName,baseRefName,changedFiles"
    return json.loads(gh("pr", "view", number, "--repo", repo, "--json", fields))


def pr_runs(repo, head):
    page = json.loads(gh("api", f"repos/{repo}/actions/runs?head_sha={head}&per_page=100"))
    runs = page["workflow_runs"]
    if page["total_count"] != len(runs):
        raise ValueError(f"the head has {page['total_count']} workflow runs and one page lists {len(runs)}")
    return runs


def pr_files(repo, number):
    text, files, decoder, at = gh("api", "--paginate", f"repos/{repo}/pulls/{number}/files"), [], json.JSONDecoder(), 0
    while at < len(text):
        if text[at].isspace():
            at += 1
            continue
        page, at = decoder.raw_decode(text, at)
        files += [f for part in page for f in (part if isinstance(part, list) else [part])]
    return files


def unstated_second_reviewers(text):
    missing = []
    for reviewer in dict.fromkeys(m.lower() for m in SECOND_REVIEWER.findall(text)):
        rest = SECOND_REVIEWER.sub("", text)
        named = re.compile(rf"(?<![\w-]){re.escape(reviewer)}(?![\w-])", re.I)
        not_run = re.search(rf"(?<![\w-]){re.escape(reviewer)}\s+not run:\s*\S", rest, re.I)
        sentences = re.split(r"(?<=[.!?])\s+|\n", rest)
        cited = any(named.search(s) and OUTCOME_TOKEN.search(s) for s in sentences)
        if not (not_run or cited):
            missing.append(reviewer)
    return missing


def readme_front(path):
    scalars, lists, key = {}, {}, None
    lines = path.read_text(errors="replace").split("\n") if path.is_file() else []
    for line in lines[1:] if lines and lines[0] == "---" else []:
        if line == "---":
            break
        if m := re.match(r"^([\w-]+):[ \t]*(.*?)[ \t]*$", line):
            key, value = m.groups()
            scalars[key] = value.strip("'\"")
            if value.startswith("["):
                lists[key] = [v.strip().strip("'\"") for v in value.strip("[]").split(",") if v.strip()]
        elif key and (m := re.match(r"^[ \t]+-[ \t]+(.*?)[ \t]*$", line)):
            lists.setdefault(key, []).append(m.group(1).strip("'\""))
    return scalars, lists


def find_readme(task, workflow_dir):
    for folder in ([Path(workflow_dir)] if workflow_dir else [task.parent, task.parent.parent]):
        scalars, lists = readme_front(folder / "README.md")
        if "trunk" in scalars:
            return folder, scalars, lists
    return None, {}, {}


def repo_root(folder):
    return next((p for p in [folder.resolve(), *folder.resolve().parents] if (p / ".git").exists()), None)


def never_paths(paths, workflow_dir, scalars):
    extra = [re.compile(rf"^{re.escape(scalars[k].strip('/'))}(?:/|$)") for k in ("migrations-path", "adr-path") if scalars.get(k)]
    root = repo_root(workflow_dir) if workflow_dir else None
    if root:
        rel = workflow_dir.resolve().relative_to(root).as_posix()
        extra.append(re.compile(r"^README\.md$" if rel == "." else rf"^{re.escape(rel)}/README\.md$"))
    return [p for p in paths if any(r.search(p) for r in NEVER_PATH + extra)]


def classify(paths, never):
    if never:
        return "never"
    if paths and all(p.startswith("docs/") and p.endswith(".md") for p in paths):
        return "docs-only"
    names = {Path(p).name for p in paths}
    is_test = lambda p: Path(p).name.startswith("test_") or re.search(r"(?:\.test|\.spec|_test)\.\w+$", p)
    own_tests = lambda p: {f"test_{Path(p).name}", *(f"{Path(p).stem}{mid}{Path(p).suffix}" for mid in (".test", "_test", ".spec"))}
    code = [p for p in paths if Path(p).suffix in CODE and not is_test(p)]
    if code and all(Path(p).suffix in CODE for p in paths) and all(names & own_tests(p) for p in code):
        return "script-with-test"
    return "other"


def commit_date(path):
    done = subprocess.run(["git", "-C", str(path.parent), "log", "-1", "--format=%cs", "--", path.name], capture_output=True, text=True)
    if not done.returncode and done.stdout.strip():
        return done.stdout.strip()
    return datetime.datetime.fromtimestamp(path.stat().st_mtime, datetime.timezone.utc).strftime("%Y-%m-%d")


def points_for(task_text, gate_text, record, paths_never, facts, profile_prod, root):
    found = []
    reports = "\n".join(VALIDATION_SECTION.findall(task_text))
    prose = reports + "\n" + gate_text
    found += [("deferred", l) for l in prose.split("\n") if DEFERRED.search(l)]
    for block in FO_DECLINES.findall(task_text) + FO_DECLINES.findall(gate_text):
        found += [("fo-decline", l.strip()) for l in block.split("\n") if re.match(r"^\s*[-*] \S", l)]
    found += [("not-run", l) for l in prose.split("\n") if NOT_RUN.search(l)]
    found += [("acceptance-not-run", l) for l in reports.split("\n") if AC_NOT_RUN.search(l)]
    if record:
        since = commit_date(record)
        found += [("amendment", f"Amendment {n} dated {d}") for n, d in AMENDMENT.findall(task_text) if d >= since]
    found += [("path", p) for p in paths_never]
    if profile_prod:
        found.append(("profile", "prod"))
    surfaces = re.search(r"^Surfaces:(.*)$", task_text, re.M)
    found += [("surface", s) for s in (re.findall(r"[\w-]+", surfaces.group(1)) if surfaces else []) if s in ("db", "ui")]
    if root and (root / "release-please-config.json").exists() and not CONVENTIONAL.match(facts["title"]):
        found.append(("title", facts["title"]))
    found += [("second-reviewer", r) for r in dict.fromkeys(m.lower() for m in SECOND_REVIEWER.findall(gate_text))]
    lines = [f"point: {kind}: {tok(value)}" for kind, value in found]
    return lines[:MAX_POINTS] + ([f"point: more: {len(lines) - MAX_POINTS} not shown"] if len(lines) > MAX_POINTS else [])


def ci_problem(rollup):
    if not rollup:
        return "the check rollup is empty: no check has run on this head"
    bad = []
    for item in rollup:
        if item.get("__typename") == "StatusContext":
            ok = item.get("state") == "SUCCESS"
        else:
            ok = item.get("status") == "COMPLETED" and item.get("conclusion") == "SUCCESS"
        if not ok:
            bad.append(tok(item.get("name") or item.get("context") or "?", words=3, chars=40))
    return f"{len(bad)} of {len(rollup)} checks on this head are not finished and successful: {' '.join(bad[:5])}" if bad else None


def runs_problem(runs):
    newest = {}
    for run in runs:
        key = run.get("workflow_id")
        newest[key] = max(newest.get(key, 0), run.get("run_number", 0))
    bad = []
    for run in runs:
        superseded = run.get("run_number", 0) < newest[run.get("workflow_id")] and run.get("conclusion") in ("cancelled", "skipped")
        if not superseded and not (run.get("status") == "completed" and run.get("conclusion") == "success"):
            bad.append(tok(run.get("name") or "?", words=4, chars=40))
    return f"{len(bad)} of {len(runs)} workflow runs on this head are not finished and successful: {' '.join(bad[:5])}" if bad else None


def write_record(task, rec):
    folder = task.with_suffix("") / "merge"
    folder.mkdir(parents=True, exist_ok=True)
    taken = [int(m.group(1)) for p in folder.glob("ask-*.json") if (m := re.fullmatch(r"ask-(\d+)\.json", p.name))]
    path = folder / f"ask-{max(taken, default=0) + 1}.json"
    path.write_text(json.dumps(rec, indent=2, sort_keys=True) + "\n")
    return path


def check(args):
    task, text_file = Path(args.task), Path(args.text_file)
    pr = PR.match(args.pr)
    try:
        task_text, gate_text = task.read_text(), text_file.read_text()
    except OSError as error:
        emit(f"cannot read input: {error}")
        return 2
    if not pr:
        emit(f"--pr must look like owner/repo#N, got {tok(args.pr)}")
        return 2
    repo, number = pr.groups()
    problems, holds, nexts = [], [], []
    workflow_dir, scalars, lists = find_readme(task, args.workflow_dir)
    if not workflow_dir:
        holds.append("cannot find the workflow README with a trunk: next to the task or in --workflow-dir")

    candidates, record = dispatched_candidates(task)
    if not candidates:
        holds.append(f"no latest validation dispatch record under {task.with_suffix('')}/dispatch has a 'Candidate: <40-hex head>' line")
        nexts.append("next: hold the ask; dispatch validation of this head with a Candidate line, or tell the Captain.")
    if args.head:
        head = args.head.lower()
        if not re.fullmatch(r"[0-9a-f]{7,40}", head):
            holds.append(f"--head must be 7-40 hexadecimal characters, got {tok(args.head)}")
            head = None
    else:
        try:
            head = run_gh(repo, number).lower()
        except (OSError, RuntimeError, ValueError, KeyError, subprocess.SubprocessError) as error:
            holds.append(f"cannot read the head of {args.pr}: {error}")
            head = None
    if candidates and head:
        if not any(c.startswith(head) for c in candidates):
            problems.append(f"PR head {head} differs from dispatched candidate {' '.join(candidates)} (latest validation record {record.name})")
            nexts.append("next: hold the ask; revalidate this head or tell the Captain the difference.")

    facts = files = runs = None
    try:
        facts, files = pr_facts(repo, number), pr_files(repo, number)
        runs = pr_runs(repo, str(facts["headRefOid"]).lower())
    except (OSError, RuntimeError, ValueError, KeyError, subprocess.SubprocessError) as error:
        holds.append(f"cannot read the pull request {args.pr}: {error}")
    if facts is not None:
        full = str(facts.get("headRefOid", "")).lower()
        if head and not full.startswith(head):
            problems.append(f"PR head is now {full}, not {head}: the checks below belong to another commit")
            nexts.append("next: hold the ask; read the PR head again and revalidate it, or tell the Captain.")
        if (why := ci_problem(facts.get("statusCheckRollup"))):
            problems.append(why)
            nexts.append("next: hold the ask until the required CI has finished green on this head.")
        if runs is not None and (why := runs_problem(runs)):
            problems.append(why)
            nexts.append("next: hold the ask until every workflow run on this head has finished green.")
        if facts.get("isDraft"):
            problems.append("the PR is a draft")
            nexts.append("next: hold the ask; mark the PR ready under the Captain's authority and let its CI finish.")
        if facts.get("mergeable") != "MERGEABLE":
            problems.append(f"the PR is not mergeable: {tok(facts.get('mergeable'), words=1, chars=20)}")
            nexts.append("next: hold the ask until the PR merges cleanly into the trunk.")
        if scalars.get("trunk") and facts.get("baseRefName") != scalars["trunk"]:
            problems.append(f"the PR base {tok(facts.get('baseRefName'), words=1, chars=60)} is not the trunk {tok(scalars['trunk'], words=1, chars=60)}")
            nexts.append("next: hold the ask; the PR does not target the trunk, tell the Captain.")
        if len(files) != facts.get("changedFiles"):
            problems.append(f"the changed-file list has {len(files)} files but the PR reports {tok(facts.get('changedFiles'), words=1, chars=12)}")
            nexts.append("next: hold the ask; the changed-file list is incomplete, tell the Captain.")

    security_errors, security_note = [], None
    at_head = [c for c in candidates if head and c.startswith(head)]
    if at_head:
        try:
            from validation_security import check_task as security_check
            security_errors, security_note = security_check(task, at_head)
        except (OSError, UnicodeDecodeError) as error:
            security_errors = [f"cannot read the validation security review: {error}"]
    for error in security_errors:
        problems.append(error)
        nexts.append("next: hold the ask; run the validation security review at this head, or tell the Captain.")

    for reviewer in unstated_second_reviewers(gate_text):
        nexts.append("next: hold the ask until each second reviewer has an outcome.")
        problems.append(f"second reviewer {reviewer} has no stated outcome: "
                        f"add '{reviewer} not run: <reason>' or a review:<id> or comment:<id> in a sentence naming {reviewer}")

    emit(*problems, *holds)
    if problems:
        emit(*dict.fromkeys(nexts))
        return 1
    if holds:
        emit(*(dict.fromkeys(nexts) or ["next: hold the ask and show the Captain these lines."]))
        return 2
    emit(f"PR head {head} equals dispatched candidate {head}; no second reviewer outcome is missing")
    if security_note:
        emit(security_note)
    paths = list(dict.fromkeys(p for f in files for p in (f.get("filename"), f.get("previous_filename")) if p))
    never = never_paths(paths, workflow_dir, scalars)
    root = repo_root(workflow_dir)
    release_pr = str(facts.get("headRefName", "")).startswith("release-please--")
    front = re.match(r"---\n(.*?)\n---", task_text, re.S)
    profile_prod = bool(front and (m := FM_PROFILE.search(front.group(1))) and m.group(1) == "prod")
    cls = classify(paths, never or release_pr or profile_prod or bool(re.search(r"^Surfaces:.*\bdb\b", task_text, re.M)))
    points = points_for(task_text, gate_text, record, never, facts, profile_prod, root)
    verdict = "merge" if not points and cls != "never" else "ask"
    emit(*points, f"class: {cls}")

    saved = write_record(task, {"pr": args.pr, "head": full, "class": cls, "verdict": verdict, "model": "not run",
                                "points": points, "next": ASK, "time": utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")})
    emit(f"record: {task.stem}/merge/{saved.name}", ASK)
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(prog="delivery_gate.py", description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    commands = parser.add_subparsers(dest="command", required=True)
    sub = commands.add_parser("check")
    sub.add_argument("task")
    sub.add_argument("--pr", required=True)
    sub.add_argument("--text-file", required=True)
    sub.add_argument("--head")
    sub.add_argument("--workflow-dir")
    args = parser.parse_args(argv)
    return check(args)


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""Check a dev2 task file: the FO-alignment record, the artifacts its Surfaces: line owes, its acceptance criteria and any Captain amendments; exit 1 on any violation."""
import argparse
import re
import sys
from collections import Counter
from pathlib import Path

KNOWN = {"ui", "db", "none"}
FO_HEADING = re.compile(r"^## FO alignment[ \t]*$", re.M)
SURFACES = re.compile(r"^Surfaces:\s*(.*)$", re.M)
VISIBLE = re.compile(r"^Visible change:\s*(.*)$", re.M)
UI_PROPOSAL = re.compile(r"^UI proposal:\s*(\S.*)$", re.M)
PREVIEW = re.compile(r"^Preview:\s*(\S.*)$", re.M)
MIGRATION = re.compile(r"^Migration source:\s*(\S.*)$", re.M)
URL = re.compile(r"^https?://\S+$")
MERMAID = re.compile(r"```mermaid\n(.*?)```", re.S)
FENCE = re.compile(r"^[ \t]*```")
GO_SPACE = "[\t\n\v\f\r \x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]*"
AC_HEADING = re.compile(rf"^{GO_SPACE}## Acceptance criteria{GO_SPACE}$", re.I)
SECTION_END = re.compile(rf"^{GO_SPACE}## ")
AC_DECLARATION = re.compile(r"\*\*(AC-[A-Za-z0-9]+)[^*\n]*\*\*")
AMENDMENTS_HEADING = re.compile(rf"^{GO_SPACE}## Captain amendments{GO_SPACE}$", re.I)
CAPTAIN_WORDS = re.compile(r"^Captain:[ \t]*\S", re.M)
SUPERSEDES = re.compile(r"^Supersedes:(.*)$", re.M)
AC_ID = re.compile(r"AC-[A-Za-z0-9]+")
DECLARATION_LINE = re.compile(r"^[ \t]*(?:>[ \t]*)*(?:(?:[-*+]|\d+[.)])[ \t]+)?\*\*(AC-[A-Za-z0-9]+)[^*\n]*\*\*")
NO_REPLACEMENT = re.compile(r"no replacement", re.I)
FRONTMATTER = re.compile(r"\A---\n(.*?\n)---\n", re.S)
FM_PROFILE = re.compile(r"""^profile:[ \t]*["']?([^\s"']+)["']?[ \t]*$""", re.M)
FM_STATUS = re.compile(r"""^status:[ \t]*["']?([^\s"']+)["']?[ \t]*$""", re.M)
REVIEW_LINE = re.compile(r"^Security review:[ \t]*(\S.*)$", re.M)
FOCUS_LINE = re.compile(r"^Security focus file:[ \t]*(\S.*)$", re.M)
FINDING_LINE = re.compile(r"^Security finding (\d+):[ \t]*(\S.*)$", re.M)
SEVERITY_SCALE = ("CRITICAL", "HIGH", "MEDIUM", "LOW")
DESIGN_SCALE = ("MAJOR", "MINOR")
DESIGN_REVIEW_LINE = re.compile(r"^Design review:[ \t]*(\S.*)$", re.M)
DESIGN_FINDING_LINE = re.compile(r"^Design finding (\d+):[ \t]*(\S.*)$", re.M)
REPORT_FINDINGS_KEY = re.compile(r"^([ \t]+)findings:(.*)$", re.M)
REPORT_ROOT_LINE = re.compile(r"^tob_security_review:", re.M)
FINDINGS_LINE = re.compile(r"^[ \t]*(?:-[ \t]+)?findings:", re.M)
SEVERITY_LINE = re.compile(r"^[ \t]*(?:-[ \t]+)?severity:", re.M)
ITEM_FIRST_KEY = re.compile(r"[A-Za-z_][\w-]*:")
TABLE = re.compile(r"^[ \t]*\|.*\|[ \t]*\n[ \t]*\|[ \t:|-]*-[ \t:|-]*\|?[ \t]*$", re.M)


def split_fo(text):
    fo, body, current = [], [], False
    for line in text.split("\n"):
        if line.startswith("## "):
            current = line[3:].strip() == "FO alignment"
            body.append(line)
            continue
        (fo if current else body).append(line)
    return "\n".join(fo), "\n".join(body)


def has_erdiagram(body):
    for block in MERMAID.findall(body):
        first = next((l.strip() for l in block.split("\n") if l.strip()), "")
        if first == "erDiagram":
            return True
    return False


def check_ui(name, body, task_dir, errors):
    proposal = UI_PROPOSAL.search(body)
    if not proposal:
        errors.append(f"{name}: surface 'ui' needs a 'UI proposal:' line with text")
    preview = PREVIEW.search(body)
    if not preview:
        errors.append(f"{name}: surface 'ui' needs a 'Preview:' line")
        return
    value = preview.group(1).strip()
    if URL.match(value):
        return
    target = Path(value)
    if not target.is_absolute():
        target = task_dir / value
    if not target.exists():
        errors.append(f"{name}: surface 'ui' Preview '{value}' does not exist")


def check_db(name, body, errors):
    if not MIGRATION.search(body):
        errors.append(f"{name}: surface 'db' needs a 'Migration source:' line with a value")
    if not (has_erdiagram(body) or TABLE.search(body)):
        errors.append(f"{name}: surface 'db' needs a schema shown as a Mermaid erDiagram or a markdown table")


def section(lines, heading):
    for start, line in enumerate(lines):
        if heading.match(line):
            end = next((i for i in range(start + 1, len(lines)) if SECTION_END.match(lines[i])), len(lines))
            return lines[start + 1:end]
    return None


def unfenced(lines):
    kept, inside = [], False
    for line in lines:
        if FENCE.match(line):
            inside = not inside
        elif not inside:
            kept.append(line)
    return kept


def check_criteria(name, lines, errors):
    body = section(lines, AC_HEADING)
    if body is None:
        errors.append(f"{name}: missing '## Acceptance criteria' section")
        return set()
    declared = {found for line in body for found in AC_DECLARATION.findall(line)}
    if not declared:
        errors.append(f"{name}: '## Acceptance criteria' declares no criterion (a '**AC-<id>**' bold line)")
    return declared


def declarations(lines):
    return [(found.group(1), line) for line in lines for found in [DECLARATION_LINE.match(line)] if found]


def check_amendments(name, lines, declared, errors):
    body = section(unfenced(lines), AMENDMENTS_HEADING)
    if body is None:
        return
    entries = re.split(r"(?m)^(?=### )", "\n".join(body))[1:]
    moved = [declarations(e.split("\n")[1:]) for e in entries]
    live = declarations(section(lines, AC_HEADING) or [])
    for index, entry in enumerate(entries):
        title = entry.split("\n", 1)[0].strip()
        if not CAPTAIN_WORDS.search(entry):
            errors.append(f"{name}: '{title}' has no 'Captain:' line with his words")
        line = SUPERSEDES.search(entry)
        value = line.group(1) if line else ""
        waiver = NO_REPLACEMENT.search(value)
        named = set(AC_ID.findall(value[:waiver.start()] if waiver else value))
        for superseded in sorted(named & declared):
            errors.append(f"{name}: '{title}' supersedes {superseded} but it is still declared in '## Acceptance criteria'")
        held = {found for found, _ in moved[index]}
        if held - named:
            errors.append(f"{name}: '{title}' holds {', '.join(sorted(held - named))} but its 'Supersedes:' line does not name them")
        digits = re.search(r"\d+", title)
        number = digits.group() if digits else str(index + 1)
        marker = re.compile(rf"Amended by Captain, amendment {number}(?!\d)")
        others = [pair for i, pairs in enumerate(moved) if i != index for pair in pairs]
        if named and not waiver and not any(marker.search(text) for _, text in live + others):
            errors.append(f"{name}: '{title}' supersedes {', '.join(sorted(named))} but no criterion says 'Amended by Captain, amendment {number}' and its 'Supersedes:' line does not say 'no replacement'")


def report_severities(text, scale=SEVERITY_SCALE):
    key = REPORT_FINDINGS_KEY.search(text)
    indent = len(key.group(1))
    rest = re.sub(r"(?:^|[ \t]+)#.*$", "", key.group(2)).strip()
    if rest == "[]":
        return [], []
    if rest:
        return None, ["has a 'findings' value that is not a list"]
    items = []
    item_indent = None
    for line in text[key.end():].split("\n"):
        body = line.lstrip(" ")
        if not body or body.startswith("#"):
            continue
        depth = len(line) - len(body)
        marker = body == "-" or body.startswith("- ")
        if depth < indent or (depth == indent and not marker):
            break
        if item_indent is None:
            if not marker:
                return None, ["has a 'findings' value that is not a list"]
            item_indent = depth
        if depth < item_indent or (depth == item_indent and not marker):
            return None, ["has a 'findings' list whose items do not share one indent"]
        if depth == item_indent:
            items.append([])
        items[-1].append((depth, body))
    if not items:
        return None, ["has a 'findings' key with no items (an empty list is written 'findings: []')"]
    severities, problems = [], []
    for number, item in enumerate(items, 1):
        first = re.match(r"- +", item[0][1])
        if not first or not ITEM_FIRST_KEY.match(item[0][1][first.end():]):
            problems.append(f"has findings item {number} that is not a 'key: value' entry")
            continue
        key_indent = item[0][0] + first.end()
        lines = [item[0][1][first.end():]] + [b for d, b in item[1:] if d == key_indent]
        found = next((b for b in lines if b.startswith("severity:")), None)
        if found is None:
            problems.append(f"has findings item {number} with no 'severity:' line")
            continue
        value = re.sub(r"[ \t]+#.*$", "", found[len("severity:"):]).strip().strip("\"'")
        if value not in scale:
            problems.append(f"has findings item {number} with severity '{value}', not one of {', '.join(scale)}")
            continue
        severities.append(value)
    return severities, problems


def findings_is_direct_child(text, root, key):
    line = text[key.start():].split("\n", 1)[0]
    indent = len(line) - len(line.lstrip(" \t"))
    between = [b for b in text[root.end():key.start()].split("\n")[1:-1] if b.strip() and not b.lstrip().startswith("#")]
    if key.start() < root.end() or not line.lstrip(" \t").startswith("findings:") or any(not b[0].isspace() for b in between):
        return False
    first = (between or [line])[0]
    return indent > 0 and indent == len(first) - len(first.lstrip(" \t"))


def root_value(text, root):
    rest = text[root.end():].split("\n", 1)[0]
    return re.sub(r"(?:^|[ \t]+)#.*$", "", rest).strip()


def report_shape(text, root="tob_security_review"):
    roots = list(re.compile(rf"^{root}:", re.M).finditer(text))
    keys = list(FINDINGS_LINE.finditer(text))
    problems = []
    if len(roots) != 1:
        problems.append(f"is not a {root} report: {len(roots)} '{root}:' lines at column 0, expected exactly 1")
    if len(keys) != 1:
        problems.append(f"has {len(keys)} 'findings:' lines, expected exactly 1")
    if len(roots) == 1 and root_value(text, roots[0]):
        problems.append(f"has a '{root}:' line with a value after its colon, so its children are not a mapping")
    if not problems and not findings_is_direct_child(text, roots[0], keys[0]):
        problems.append(f"has a 'findings:' line that is not a direct child of '{root}:'")
    return problems


def repeated(found, label, name, errors):
    for n, count in sorted(Counter(int(n) for n, _ in found).items()):
        if count > 1:
            errors.append(f"{name}: '{label} finding {n}:' appears more than once; write one disposition per finding")


def check_security(path, body, declared, errors):
    name = path.name
    review = REVIEW_LINE.search(body)
    if not review:
        errors.append(f"{name}: a prod task needs a 'Security review:' line naming the saved report")
        return None
    if len(REVIEW_LINE.findall(body)) > 1:
        errors.append(f"{name}: {len(REVIEW_LINE.findall(body))} 'Security review:' lines, expected exactly 1; a rerun replaces the old line with the last report")
        return None
    value = review.group(1).strip()
    if value.lower().startswith("not run"):
        errors.append(f"{name}: security review not run ({value}); a missing reviewer holds the stage")
        return None
    folder = path.parent if path.name == "index.md" else path.parent / path.stem
    report = folder / value
    if Path(value).is_absolute() or ".." in Path(value).parts or not report.is_file():
        errors.append(f"{name}: 'Security review:' names '{value}', not a report file inside the task folder")
        return None
    text = report.read_text()
    shape = report_shape(text)
    if shape:
        errors.extend(f"{name}: '{value}' {problem}" for problem in shape)
        return None
    if not FOCUS_LINE.search(body):
        errors.append(f"{name}: a prod task needs a 'Security focus file:' line (a path, or none)")
    severities, problems = report_severities(text)
    if problems:
        errors.extend(f"{name}: '{value}' {problem}" for problem in problems)
        return None
    plain = len(SEVERITY_LINE.findall(text))
    if plain != len(severities):
        errors.append(f"{name}: '{value}' has {plain} 'severity:' lines but {len(severities)} in its findings items; every severity line must be a key of one findings item")
        return None
    found = len(severities)
    lines = {int(n): v.strip() for n, v in FINDING_LINE.findall(body)}
    repeated(FINDING_LINE.findall(body), "Security", name, errors)
    tally = {"ac": 0, "declined": 0, "decision": 0}
    for number in range(1, found + 1):
        entry = lines.get(number, "")
        if re.fullmatch(r"AC-[A-Za-z0-9]+", entry.split()[0] if entry else "") and entry.split()[0] in declared:
            tally["ac"] += 1
        elif re.match(r"declined:\s*\S", entry) and severities[number - 1] in ("MEDIUM", "LOW"):
            tally["declined"] += 1
        elif re.match(r"Needs decision:\s*\S", entry):
            tally["decision"] += 1
        else:
            errors.append(f"{name}: report finding {number} has no 'Security finding {number}:' line naming a declared AC-<id>, 'declined: <reason>' (MEDIUM or LOW only) or 'Needs decision: <text>'")
    for number in sorted(set(lines) - set(range(1, found + 1))):
        errors.append(f"{name}: 'Security finding {number}:' has no finding in '{value}' ({found} listed)")
    return f"security review {value}: {found} findings, {tally['ac']} acceptance criteria, {tally['declined']} declined, {tally['decision']} decisions"


def check_design_review(path, body, declared, previews, errors):
    name = path.name
    review = DESIGN_REVIEW_LINE.search(body)
    if not review:
        errors.append(f"{name}: a ui task needs a 'Design review:' line naming the saved report")
        return None
    if len(DESIGN_REVIEW_LINE.findall(body)) > 1:
        errors.append(f"{name}: {len(DESIGN_REVIEW_LINE.findall(body))} 'Design review:' lines, expected exactly 1; a rerun replaces the old line with the last report")
        return None
    value = review.group(1).strip()
    if value.lower().startswith("not run"):
        errors.append(f"{name}: design review not run ({value}); a missing reviewer holds the stage")
        return None
    folder = path.parent if path.name == "index.md" else path.parent / path.stem
    report = folder / value
    if Path(value).is_absolute() or ".." in Path(value).parts or not report.is_file():
        errors.append(f"{name}: 'Design review:' names '{value}', not a report file inside the task folder")
        return None
    text = report.read_text()
    shape = report_shape(text, "design_review")
    if shape:
        errors.extend(f"{name}: '{value}' {problem}" for problem in shape)
        return None
    child = re.match(r"[ \t]*", FINDINGS_LINE.search(text).group(0)).group(0)
    block = re.search(r"^design_review:.*\n((?:[ \t].*\n|[ \t]*\n|#.*\n)*)", text + "\n", re.M).group(1)
    named = re.findall(rf"^{child}preview:[ \t]*(.*)$", block, re.M)
    if len(named) != 1:
        errors.append(f"{name}: '{value}' has {len(named)} 'preview:' lines directly under 'design_review:', expected exactly 1")
    elif named[0].strip().strip("\"'") not in previews:
        errors.append(f"{name}: '{value}' reviewed preview '{named[0].strip().strip(chr(34)+chr(39))}' but the task's 'Preview:' line names {', '.join(repr(p) for p in previews)}")
    severities, problems = report_severities(text, DESIGN_SCALE)
    if problems:
        errors.extend(f"{name}: '{value}' {problem}" for problem in problems)
        return None
    plain = len(SEVERITY_LINE.findall(text))
    if plain != len(severities):
        errors.append(f"{name}: '{value}' has {plain} 'severity:' lines but {len(severities)} in its findings items; every severity line must be a key of one findings item")
        return None
    found = len(severities)
    lines = {int(n): v.strip() for n, v in DESIGN_FINDING_LINE.findall(body)}
    repeated(DESIGN_FINDING_LINE.findall(body), "Design", name, errors)
    tally = {"ac": 0, "fixed": 0, "declined": 0, "decision": 0}
    for number in range(1, found + 1):
        entry = lines.get(number, "")
        if re.fullmatch(r"AC-[A-Za-z0-9]+", entry.split()[0] if entry else "") and entry.split()[0] in declared:
            tally["ac"] += 1
        elif re.match(r"fixed:\s*\S", entry):
            tally["fixed"] += 1
        elif re.match(r"declined:\s*\S", entry) and severities[number - 1] == "MINOR":
            tally["declined"] += 1
        elif re.match(r"Needs decision:\s*\S", entry):
            tally["decision"] += 1
        else:
            errors.append(f"{name}: report finding {number} has no 'Design finding {number}:' line naming a declared AC-<id>, 'fixed: <what changed>', 'declined: <reason>' (MINOR only) or 'Needs decision: <text>'")
    for number in sorted(set(lines) - set(range(1, found + 1))):
        errors.append(f"{name}: 'Design finding {number}:' has no finding in '{value}' ({found} listed)")
    return f"design review {value}: {found} findings, {tally['fixed']} fixed, {tally['ac']} criteria, {tally['declined']} declined, {tally['decision']} decisions"


def check_task(path, seed=False, notes=None):
    errors = []
    text = path.read_text()
    if not FO_HEADING.search(text):
        errors.append(f"{path.name}: missing '## FO alignment' section")
    _, body = split_fo(text)
    fo, _ = split_fo("\n".join(unfenced(text.split("\n"))))
    match = SURFACES.search(fo)
    surfaces = set()
    if len(SURFACES.findall(fo)) > 1:
        errors.append(f"{path.name}: '## FO alignment' has {len(SURFACES.findall(fo))} 'Surfaces:' lines, expected exactly 1")
    if not match or not match.group(1).strip():
        errors.append(f"{path.name}: '## FO alignment' needs a non-empty 'Surfaces:' line")
    else:
        raw = [v.strip() for v in match.group(1).split(",") if v.strip()]
        surfaces = set(raw)
        unknown = sorted(surfaces - KNOWN)
        if unknown:
            errors.append(f"{path.name}: 'Surfaces:' has unknown value(s) {', '.join(unknown)}")
        if "none" in surfaces and len(surfaces) > 1:
            errors.append(f"{path.name}: 'Surfaces:' combines 'none' with other values")

    visible = VISIBLE.search(fo)
    if not visible:
        errors.append(f"{path.name}: '## FO alignment' needs a 'Visible change:' line")
    else:
        value = visible.group(1).strip()
        if value.lower() != "none" and "ui" not in surfaces:
            errors.append(f"{path.name}: 'Visible change:' is not 'none' but 'Surfaces:' has no 'ui'")
        if value.lower() == "none" and "ui" in surfaces:
            errors.append(f"{path.name}: 'Visible change: none' contradicts 'ui' in 'Surfaces:'")

    if seed:
        return errors
    if "ui" in surfaces:
        check_ui(path.name, body, path.resolve().parent, errors)
    if "db" in surfaces:
        check_db(path.name, body, errors)
    lines = text.split("\n")
    declared = check_criteria(path.name, lines, errors)
    check_amendments(path.name, lines, declared, errors)
    front = FRONTMATTER.match(text)
    profile, status = (FM_PROFILE.search(front.group(1)), FM_STATUS.search(front.group(1))) if front else (None, None)
    plain = "\n".join(unfenced(lines))
    if profile and status and (profile.group(1), status.group(1)) == ("prod", "ideation"):
        summary = check_security(path, plain, declared, errors)
        if summary and notes is not None:
            notes.append(summary)
    if "ui" in surfaces and status and status.group(1) == "ideation":
        shown = [v.strip() for v in PREVIEW.findall("\n".join(unfenced(body.split("\n"))))]
        summary = check_design_review(path, plain, declared, shown, errors)
        if summary and notes is not None:
            notes.append(summary)
    return errors


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    check = sub.add_parser("check", help="check a task file: FO alignment, surface artifacts, acceptance criteria, Captain amendments")
    check.add_argument("--seed", action="store_true", help="check only the FO-alignment record, before ideation is dispatched")
    check.add_argument("task")
    args = parser.parse_args(argv)
    path = Path(args.task)
    notes = []
    errors = check_task(path, seed=args.seed, notes=notes)
    for error in errors:
        print(error)
    if not errors:
        print(f"{path.name}: {'FO alignment recorded' if args.seed else 'design surfaces presentable'}")
        for note in notes:
            print(note)
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Check a docs/adr directory against the dev2 ADR format; exit 1 on any violation."""
import argparse
import re
import subprocess
import sys
from pathlib import Path

NAME = re.compile(r"^(\d{4})-[a-z0-9]+(?:-[a-z0-9]+)*\.md$")
SECTIONS = ["Status", "Context", "Decision", "Consequences"]
STATUS = re.compile(r"^(Proposed|Accepted|Deprecated|Superseded by (\d{4}))$")
LEGACY = re.compile(r"^Status: Legacy\b", re.M)
SKIP = {"README.md", "index.md", "template.md"}


def sections(text):
    found, current = {}, None
    for line in text.split("\n"):
        if line.startswith("## "):
            current = line[3:].strip()
            found.setdefault("_order", []).append(current)
            found[current] = []
        elif current:
            found[current].append(line)
    return found


def check_file(path, numbers):
    errors, text = [], path.read_text()
    number = int(NAME.match(path.name).group(1))
    head = "\n".join(text.split("\n")[:30])
    if LEGACY.search(head):
        return errors, True
    first = next((l for l in text.split("\n") if l.strip()), "")
    title = re.match(r"^# (\d+)\. \S", first)
    if not title or int(title.group(1)) != number:
        errors.append(f"{path.name}: first line must be '# {number}. <title>'")
    preamble = text.split("\n## ", 1)[0]
    if not re.search(r"^Date: \d{4}-\d{2}-\d{2}$", preamble, re.M):
        errors.append(f"{path.name}: needs a 'Date: YYYY-MM-DD' line before the first section")
    found = sections(text)
    if found.get("_order") != SECTIONS:
        errors.append(f"{path.name}: sections must be exactly {', '.join(SECTIONS)} in that order")
    for name in SECTIONS:
        if not "".join(found.get(name, [])).strip():
            errors.append(f"{path.name}: section '{name}' is empty")
    status = next((l.strip() for l in found.get("Status", []) if l.strip()), "")
    matched = STATUS.match(status)
    if not matched:
        errors.append(f"{path.name}: status '{status}' is not Proposed, Accepted, Deprecated or 'Superseded by NNNN'")
    elif matched.group(2) and int(matched.group(2)) not in numbers:
        errors.append(f"{path.name}: superseded by {matched.group(2)}, which does not exist")
    decision = "\n".join(found.get("Decision", []))
    for label in ("**Words:**", "**Options considered:**"):
        if label not in decision:
            errors.append(f"{path.name}: Decision needs a '{label}' line")
    return errors, False


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("adr_dir")
    parser.add_argument("--require", nargs="*", default=[], help="ADR numbers this change must add or update")
    parser.add_argument("--since", help="base commit; every record added or changed since it is required")
    args = parser.parse_args(argv)
    root = Path(args.adr_dir)
    required = list(args.require)
    if args.since:
        diff = subprocess.run(["git", "-C", str(root), "diff", "--name-only", "--relative", "--diff-filter=AMR",
                               args.since, "--", "."], capture_output=True, text=True)
        if diff.returncode:
            print(f"--since {args.since}: {diff.stderr.strip() or 'git diff failed'}")
            return 2
        untracked = subprocess.run(["git", "-C", str(root), "ls-files", "--others", "--exclude-standard", "--", "."],
                                   capture_output=True, text=True).stdout
        required += [m.group(1) for m in map(NAME.match, (diff.stdout + untracked).split()) if m]
    errors, files = [], {}
    for path in sorted(root.glob("*.md")):
        if path.name in SKIP:
            continue
        match = NAME.match(path.name)
        if not match:
            errors.append(f"{path.name}: file name must be NNNN-short-title.md")
            continue
        number = int(match.group(1))
        if number in files:
            errors.append(f"{path.name}: number {number} is also used by {files[number].name}")
        files[number] = path
    legacy = set()
    for number, path in files.items():
        found, is_legacy = check_file(path, set(files))
        errors += found
        if is_legacy:
            legacy.add(number)
    for number, raw in {int(raw): raw for raw in reversed(required)}.items():
        if number not in files:
            errors.append(f"required ADR {raw} does not exist")
        elif number in legacy and raw in args.require:
            errors.append(f"required ADR {raw} is a legacy record; a new ruling needs its own file")
        elif number in legacy:
            continue
        elif "**Recommended:**" not in "\n".join(sections(files[number].read_text()).get("Decision", [])):
            errors.append(f"required ADR {raw}: Decision needs a '**Recommended:**' line; a record written "
                          "before that line existed takes '**Recommended:** not recorded', never a reconstructed recommendation")
    for error in errors:
        print(error)
    if not errors:
        unchecked = "" if args.since or args.require else "; changed records not checked (no --since or --require)"
        print(f"{len(files)} ADR file(s) checked, {len(legacy)} legacy{unchecked}")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""Refuse candidates that change an applied migration or take a number another task holds, and reserve numbers per task.

check   exit 0 clean, 1 findings, 2 misconfiguration. Rules: R1 a migration present at the merge-base is
        modified or deleted; R2 the same against every 'Applied at: <env> <sha>' commit; R3 an added migration
        number is not above the base tip's highest; R4 an added migration or ADR number is not in the task's
        'Migration:' / 'ADR:' lines; R5 an added ADR number exists on the base tip; R6 a task whose frontmatter says
        'profile: poc' differs from the merge-base anywhere under the migrations directory.
reserve prints 'Migration: NNNN' or 'ADR: NNNN' (one above the base tip and every other task file, never
        filling a gap); a task that already holds a line gets it back. One number per kind per task.
Limits: only files named NNNN_name.sql count as migrations, so meta/_journal.json and snapshots are not checked (R6 does check them);
a deploy nobody recorded as 'Applied at:' is not detected; run 'git -C <repo> fetch' first, the base tip is what is local.
Task lines are read from the task's '## Number guards' section.
"""
import argparse
import posixpath
import re
import subprocess
import sys
from pathlib import Path

MIGRATION = re.compile(r"^(\d+)_.+\.sql$")
ADR = re.compile(r"^(\d{4})-.+\.md$")
KINDS = {"migration": ("Migration", MIGRATION), "adr": ("ADR", ADR)}


class Misconfigured(Exception):
    pass


def git(repo, *args):
    done = subprocess.run(["git", "-C", repo, *args], capture_output=True, text=True)
    if done.returncode:
        raise Misconfigured(f"git {' '.join(args)}: {done.stderr.strip()}")
    return done.stdout


def resolve(repo, ref, what="ref"):
    done = subprocess.run(["git", "-C", repo, "rev-parse", "--verify", "--quiet", f"{ref}^{{commit}}"],
                          capture_output=True, text=True)
    if done.returncode:
        raise Misconfigured(f"cannot resolve {what} '{ref}' in {repo}")
    return done.stdout.strip()


def frontmatter(readme):
    if not readme.is_file():
        raise Misconfigured(f"no workflow README at {readme}")
    lines = readme.read_text().split("\n")
    found = {}
    for line in lines[1:] if lines[0] == "---" else []:
        if line == "---":
            break
        match = re.match(r"^([\w-]+):[ \t]*(.*?)[ \t]*$", line)
        if match:
            found[match.group(1)] = match.group(2).strip("'\"")
    return found


def task_facts(path):
    task = Path(path)
    if not task.is_file():
        raise Misconfigured(f"task file {task} does not exist")
    text = task.read_text(errors="replace")
    section = re.search(r"^## Number guards[ \t]*\n(.*?)(?=^## |\Z)", text, re.M | re.S)
    body = section.group(1) if section else ""
    surfaces = re.search(r"^Surfaces:(.*)$", text, re.M)
    return {
        "migration": {int(n) for n in re.findall(r"^Migration:[ \t]*(\d+)[ \t]*$", body, re.M)},
        "adr": {int(n) for n in re.findall(r"^ADR:[ \t]*(\d+)[ \t]*$", body, re.M)},
        "applied": re.findall(r"^Applied at:[ \t]*(\S+)[ \t]+([0-9a-f]{7,40})[ \t]*$", body, re.M),
        "poc": frontmatter(task).get("profile") == "poc",
        "surfaces": set(re.split(r"[\s,]+", surfaces.group(1).strip())) if surfaces else set(),
    }


def numbered(repo, ref, directory, pattern):
    found = {}
    for path in git(repo, "ls-tree", "--name-only", ref, directory.rstrip("/") + "/").splitlines():
        match = pattern.match(posixpath.basename(path))
        if match:
            found.setdefault(int(match.group(1)), []).append(posixpath.basename(path))
    return found


def added_changed(repo, old, new, directory, pattern):
    """Return (added files, files present at old and modified or deleted at new) among numbered files in directory."""
    added, touched = [], []
    out = git(repo, "diff", "--name-status", "--no-renames", old, new, "--", directory.rstrip("/") + "/")
    for line in out.splitlines():
        status, path = line.split("\t", 1)
        if posixpath.dirname(path) != directory.rstrip("/") or not pattern.match(posixpath.basename(path)):
            continue
        (added if status == "A" else touched).append((status, path))
    return added, touched


def settings(args):
    cfg = frontmatter(Path(args.workflow_dir) / "README.md") if args.workflow_dir else {}
    base = args.base
    if not base and cfg.get("trunk"):
        remote = f"origin/{cfg['trunk']}"
        base = remote if subprocess.run(["git", "-C", args.repo, "rev-parse", "--verify", "--quiet", remote],
                                        capture_output=True).returncode == 0 else cfg["trunk"]
    if not base:
        raise Misconfigured("no base: pass --base, or --workflow-dir whose README declares trunk:")
    return {
        "migrations": args.migrations_path or cfg.get("migrations-path"),
        "adr": args.adr_path or cfg.get("adr-path") or "docs/adr",
        "base": base,
        "state": getattr(args, "state_dir", None) or (cfg.get("state") and str(Path(args.workflow_dir) / cfg["state"])),
    }


def require_migrations(repo, base, directory):
    files = numbered(repo, base, directory, MIGRATION)
    if not files:
        raise Misconfigured(f"no migration file matching NNNN_name.sql under '{directory}' at {base} "
                            "(the path is absent there or holds none)")
    return files


def check(args):
    repo, cfg = args.repo, settings(args)
    facts = task_facts(args.task) if args.task else None
    directory = cfg["migrations"]
    if not directory and facts and "db" in facts["surfaces"]:
        raise Misconfigured("task has Surfaces: db but no migrations-path is declared "
                            "(pass --migrations-path or set migrations-path: in the workflow README)")
    base, head = resolve(repo, cfg["base"], "base"), resolve(repo, args.head, "head")
    merge_base = git(repo, "merge-base", base, head).strip()
    applied = [("cli", ref) for ref in args.applied_ref] + (facts["applied"] if facts else [])
    applied = [(env, ref, resolve(repo, ref, f"applied commit ({env})")) for env, ref in applied]
    out = []

    def fail(rule, path, reason):
        out.append(f"FAIL {rule}: {path}: {reason}")

    if directory:
        base_numbers = require_migrations(repo, base, directory)
        added, touched = added_changed(repo, merge_base, head, directory, MIGRATION)
        for status, path in touched:
            fail("R1", path, f"{status} since the merge-base; a migration on the base branch must not change, "
                 "revert it and add a new migration")
        for env, ref, sha in applied:
            for status, path in added_changed(repo, sha, head, directory, MIGRATION)[1]:
                fail("R2", path, f"{status} since {sha[:12]}, applied at {env}; revert it and add a new migration")
        top = max(base_numbers)
        for _, path in added:
            number = int(MIGRATION.match(posixpath.basename(path)).group(1))
            if number in base_numbers:
                fail("R3", path, f"base already has {number:04d} ({base_numbers[number][0]})")
            elif number < top:
                fail("R3", path, f"number {number:04d} is not above the base maximum {top:04d}")
            if facts is not None and number not in facts["migration"]:
                fail("R4", path, f"number {number:04d} is not in the task's Migration: lines")
        if facts and facts["poc"]:
            for line in git(repo, "diff", "--name-status", "--no-renames", merge_base, head,
                            "--", directory.rstrip("/") + "/").splitlines():
                status, path = line.split("\t", 1)
                fail("R6", path, f"{status} under the migrations directory; a POC task changes none of it")
    else:
        out.append("migration guard skipped: no migrations-path declared")
    adr_base = numbered(repo, base, cfg["adr"], ADR)
    for _, path in added_changed(repo, merge_base, head, cfg["adr"], ADR)[0]:
        number = int(ADR.match(posixpath.basename(path)).group(1))
        if number in adr_base:
            fail("R5", path, f"base already has {number:04d} ({adr_base[number][0]})")
        if facts is not None and number not in facts["adr"]:
            fail("R4", path, f"number {number:04d} is not in the task's ADR: lines")
    if facts is None:
        out.append("R4 skipped: no --task given")
    failed = any(line.startswith("FAIL") for line in out)
    print("\n".join(out + ([] if failed else ["PASS: no findings"])))
    print(f"base {base[:12]} head {head[:12]} merge-base {merge_base[:12]}")
    return 1 if failed else 0


def reserve(args):
    repo, cfg = args.repo, settings(args)
    label, pattern = KINDS[args.kind]
    facts = task_facts(args.task)
    if facts[args.kind]:
        for number in sorted(facts[args.kind]):
            print(f"{label}: {number:04d}")
        return 0
    if not cfg["state"]:
        raise Misconfigured("no state directory: pass --state-dir, or --workflow-dir whose README declares state:")
    if args.kind == "migration":
        if not cfg["migrations"]:
            raise Misconfigured("no migrations-path declared (pass --migrations-path or set it in the workflow README)")
        files = require_migrations(repo, resolve(repo, cfg["base"], "base"), cfg["migrations"])
        width = max(4, *(len(name.split("_")[0]) for names in files.values() for name in names))
    else:
        files = numbered(repo, resolve(repo, cfg["base"], "base"), cfg["adr"], pattern)
        width = 4
    taken = set(files)
    for sibling in sorted(Path(cfg["state"]).glob("*.md")):
        if sibling.resolve() != Path(args.task).resolve():
            taken |= task_facts(sibling)[args.kind]
    print(f"{label}: {max(taken, default=0) + 1:0{width}d}")
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="command", required=True)
    for name, handler in (("check", check), ("reserve", reserve)):
        cmd = sub.add_parser(name)
        cmd.set_defaults(handler=handler)
        cmd.add_argument("--repo", default=".")
        cmd.add_argument("--workflow-dir", help="workflow directory whose README supplies trunk, migrations-path, adr-path, state")
        cmd.add_argument("--base", help="base ref; default origin/<trunk>, else <trunk>")
        cmd.add_argument("--migrations-path")
        cmd.add_argument("--adr-path")
        cmd.add_argument("--task", help="task file holding the '## Number guards' section")
    sub.choices["check"].add_argument("--head", default="HEAD")
    sub.choices["check"].add_argument("--applied-ref", action="append", default=[])
    sub.choices["reserve"].add_argument("--kind", choices=KINDS, required=True)
    sub.choices["reserve"].add_argument("--state-dir")
    args = parser.parse_args(argv)
    if args.command == "reserve" and not args.task:
        parser.error("reserve needs --task")
    try:
        return args.handler(args)
    except Misconfigured as error:
        print(f"number_guards: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
